      "nct": "NCT05608434",
      "title": "Development of Virtual Reality-based Interventions to Strengthen Cognitive Skillsets Related to Attention Deficit Hyperactivity Disorder (ADHD): A Pilot Phase I and Randomized Controlled Phase II Trial",
      "status": "RECRUITING",
      "conditions": [
        "Attention Deficit Hyperactivity Disorder"
      ],
      "topic_match": "literal words in title, conditions or interventions; not clinical suitability",
      "study_type": "INTERVENTIONAL",
      "relevance": {
        "method": "literal topic words; synonyms and clinical meaning not assessed",
